// Design render for "深入了解": real React app via a Vite dev server with the proposed files swapped
// in (no dist rebuild, live service untouched), on a throwaway copy of the live database.
// The deep-dive endpoint is simulated here and replays the three REAL results in samples.json
// (generated by generate-samples.ts with the logged-in Claude CLI). No Claude call happens here.
// Run from business/:  node --experimental-strip-types ../pic/project-deep-dive-2026-11-11/render.mjs
import http from 'node:http';
import path from 'node:path';
import os from 'node:os';
import {cp,mkdtemp,readFile,rename,rm,writeFile} from 'node:fs/promises';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {createRequire} from 'node:module';

const here=path.dirname(fileURLToPath(import.meta.url)),repo=path.resolve(here,'../..'),business=path.join(repo,'business'),frontend=path.join(business,'frontend');
const require=createRequire(path.join(business,'package.json'));
const {chromium}=require('playwright-core');
const {createServer}=await import(pathToFileURL(path.join(frontend,'node_modules/vite/dist/node/index.js')).href);
const react=(await import(pathToFileURL(path.join(frontend,'node_modules/@vitejs/plugin-react/dist/index.js')).href)).default;
const {createApp}=await import(pathToFileURL(path.join(business,'backend/server.ts')).href);
const samples=JSON.parse(await readFile(path.join(here,'samples.json'),'utf8')).samples;

const temp=await mkdtemp(path.join(os.tmpdir(),'lydia-deepdive-render-'));
await cp(path.join(repo,'data/data_storage/database'),path.join(temp,'pg'),{recursive:true});
const report={date:'2026-11-11',artifact:'DESIGN_ONLY',applicationModified:false,database:'copy of the live database (read-only use)',shots:[],video:null,errors:[]};

// Simulated endpoint: POST starts a run that replays the real steps, then returns the real result.
let runMs=0;const runs=new Map();
function deepState(id,title){
 const s=samples[title];if(!runs.has(id))return {status:'none'};
 if(!s?.sections)return {status:'failed',error:{message:'设计稿只为 3 个样本项目生成了解读'},log:[]};
 const t=Date.now()-runs.get(id);
 if(t<runMs){const steps=[...s.steps.filter(x=>!x.startsWith('Claude'))];const n=Math.min(steps.length,1+Math.floor(t/1300));const shown=steps.slice(0,n);if(n>=steps.length)shown.push(`Claude 正在阅读 ${s.sources.length} 份资料`);return {status:'running',steps:shown};}
 const {steps:_,...result}=s;return {status:'ready',result};
}
let app;
const server=http.createServer(async(req,res)=>{
 const m=/^\/api\/knowledge\/projects\/([^/]+)\/deep-dive$/.exec(req.url||'');
 if(m){
  const id=decodeURIComponent(m[1]),p=await app.store.one('SELECT title FROM crawl_projects WHERE id=$1',[id]);
  if(req.method==='POST')runs.set(id,Date.now());
  res.writeHead(req.method==='POST'?202:200,{'content-type':'application/json'});res.end(JSON.stringify(deepState(id,p?.title)));return;
 }
 app.handler(req,res);
});
await new Promise(r=>server.listen(0,'127.0.0.1',r));
const origin='http://127.0.0.1:'+server.address().port;
app=await createApp({origin,dataDir:path.join(temp,'pg'),crawlStorageDir:path.join(temp,'crawl'),startWorker:false,localAutoLogin:true});
app.cli.run=async()=>{throw new Error('No inference in the deep-dive design render');};

const proposed=path.join(here,'proposed'),src=path.join(frontend,'src').replace(/\\/g,'/');
const swapped={'/src/main.jsx':'main.jsx','/src/components/KnowledgeWorkspace.jsx':'KnowledgeWorkspace.jsx','/src/components/KnowledgeMaterialDetails.jsx':'KnowledgeMaterialDetails.jsx'};
const virtual={[src+'/components/ProjectDeepDive.jsx']:'ProjectDeepDive.jsx',[src+'/deep-dive.css']:'deep-dive.css'};
const swap={name:'design-swap-deep-dive',enforce:'pre',
 resolveId(id,importer){if(!importer)return;const f=path.resolve(path.dirname(importer.split('?')[0]),id).replace(/\\/g,'/');if(virtual[f])return f;},
 async load(id){const f=id.split('?')[0].replace(/\\/g,'/');if(virtual[f])return readFile(path.join(proposed,virtual[f]),'utf8');for(const [k,v] of Object.entries(swapped))if(f.endsWith('/frontend'+k))return readFile(path.join(proposed,v),'utf8');}};
const vite=await createServer({configFile:false,root:frontend,logLevel:'error',plugins:[react(),swap],
 server:{host:'127.0.0.1',port:5311,strictPort:true,hmr:false,proxy:{'/api':{target:origin,changeOrigin:true,configure(proxy){proxy.on('proxyReq',r=>r.setHeader('origin',origin));}}}}});
await vite.listen();
const base='http://127.0.0.1:5311';

const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
async function open(viewport,{theme='light',mobile=false,video=false}={}){
 const ctx=await browser.newContext({viewport,deviceScaleFactor:video?1:mobile?3:2,...mobile?{hasTouch:true,isMobile:true}:{},...video?{recordVideo:{dir:path.join(temp,'video'),size:viewport}}:{}});
 await ctx.addInitScript(t=>{try{localStorage.setItem('lydia-theme',t);sessionStorage.setItem('lydia-tracker-toast','dismissed');}catch{}},theme);
 const page=await ctx.newPage();page.on('pageerror',e=>report.errors.push(e.message));
 await page.goto(base+'/#/knowledge');
 await page.waitForFunction(()=>document.querySelectorAll('.knowledge-object').length>0,null,{timeout:60000});
 await page.waitForTimeout(800);
 const toast=page.locator('.kt-toast button',{hasText:'稍后'});if(await toast.count())await toast.first().click();
 return {ctx,page};
}
async function pick(page,title){
 await page.fill('input[aria-label="搜索比赛项目"]',title);
 await page.waitForFunction(t=>{const a=[...document.querySelectorAll('.knowledge-object')];return a.length&&a.every(b=>b.getAttribute('aria-label').toLowerCase().includes(t.toLowerCase()));},title,{timeout:20000});
 await page.waitForTimeout(600);
 await page.evaluate(t=>{const a=[...document.querySelectorAll('.knowledge-object')];(a.find(b=>b.getAttribute('aria-label')==='查看项目 '+t)||a[0]).click();},title);
 await page.waitForFunction(t=>document.querySelector('.kw-detail h2')?.textContent===t&&document.querySelector('.kw-brief__deep'),title,{timeout:20000});
 await page.waitForTimeout(400);
}
async function shot(page,name,what,opts={}){await page.screenshot({path:path.join(here,name),animations:'disabled',...opts});report.shots.push({file:name,what});}
const scrollTo=(page,sel)=>page.evaluate(s=>document.querySelector(s)?.scrollIntoView({block:'start'}),sel);

try{
 const desk={width:1440,height:900};
 {const {ctx,page}=await open(desk);await pick(page,'Tap2ETH');
  await shot(page,'01-brief-card-button.png','选中 Tap2ETH：简介卡片右上角多了「深入了解」');
  runMs=12000;await page.locator('.kw-brief__deep').click();await page.waitForTimeout(3300);
  await shot(page,'02-reading-progress.png','点击后：中间书库区域换成解读面板，逐步显示正在读什么');
  runs.clear();runMs=0;await page.locator('.kw-deep__close').click();await page.locator('.kw-brief__deep').click();
  await page.locator('.kw-deep__overview').waitFor();await page.waitForTimeout(300);
  await shot(page,'03-tap2eth-result.png','解读完成：一句话概述、原文核对结果，以及分段要点，每条后面标着出处');
  await page.locator('.kw-deep__sec:has(h3:text("关键实现细节")) .kw-deep__cite').nth(1).click();
  await page.evaluate(()=>{const b=document.querySelector('.kw-deep__body');const h=[...b.querySelectorAll('h3')].find(x=>x.textContent==='关键实现细节');b.scrollTop=h.offsetTop-b.offsetTop-10;});await page.waitForTimeout(250);
  await shot(page,'04-quote-open.png','点开一条的出处：显示从来源里原样复制的原文，可以点链接回到原页面');
  await page.locator('.kw-deep__check input').check();await page.evaluate(()=>{const b=document.querySelector('.kw-deep__body');const h=[...b.querySelectorAll('h3')].find(x=>x.textContent==='做到了哪一步');b.scrollTop=h.offsetTop-b.offsetTop-10;});await page.waitForTimeout(250);
  await shot(page,'05-all-quotes.png','勾选「展开全部原文」：每条要点下面都显示原文');
  await page.locator('.kw-deep__check input').uncheck();await page.evaluate(()=>{const b=document.querySelector('.kw-deep__body');b.scrollTop=b.scrollHeight;});await page.waitForTimeout(250);
  await shot(page,'06-unknowns-and-sources.png','最后：资料里没说清楚的地方，读过的资料清单（含没读的 x.com 和原因）');
  await ctx.close();}
 {const {ctx,page}=await open(desk,{theme:'dark'});await pick(page,'Smart Water Guardian AI');runs.clear();await page.locator('.kw-brief__deep').click();await page.locator('.kw-deep__overview').waitFor();await page.waitForTimeout(300);
  await shot(page,'07-dark-smart-water.png','黑夜模式：Smart Water Guardian AI（GitHub 仓库是从 hackster 项目页里自动找到的）');await ctx.close();}
 {const {ctx,page}=await open(desk);await pick(page,'Tokito');runs.clear();await page.locator('.kw-brief__deep').click();await page.locator('.kw-deep__overview').waitFor();await page.waitForTimeout(300);
  await shot(page,'08-tokito.png','Tokito（devfolio）：项目页里有两个 GitHub 链接，一个不公开，清单里写明了');await ctx.close();}
 {const {ctx,page}=await open({width:390,height:844},{mobile:true});await pick(page,'Tap2ETH');runs.clear();
  await page.locator('.kw-brief__deep').scrollIntoViewIfNeeded();await shot(page,'09-phone-button.png','手机：简介卡片上的按钮');
  await page.locator('.kw-brief__deep').click();await page.locator('.kw-deep__overview').waitFor();await page.waitForTimeout(300);
  await shot(page,'10-phone-result.png','手机：解读铺满整个屏幕');await ctx.close();}
 {const {ctx,page}=await open(desk,{video:true});await pick(page,'Tap2ETH');runs.clear();runMs=7000;await page.waitForTimeout(900);
  await page.locator('.kw-brief__deep').hover();await page.waitForTimeout(500);await page.locator('.kw-brief__deep').click();
  await page.locator('.kw-deep__overview').waitFor({timeout:20000});await page.waitForTimeout(1500);
  for(const n of [0,2]){await page.locator('.kw-deep__cite').nth(n).click();await page.waitForTimeout(1100);}
  await page.locator('.kw-deep__check input').check();await page.waitForTimeout(700);
  for(let i=0;i<14;i++){await page.mouse.move(900,600);await page.mouse.wheel(0,260);await page.waitForTimeout(260);}
  await page.waitForTimeout(800);await page.locator('.kw-deep__close').click();await page.waitForTimeout(900);
  const v=page.video();await ctx.close();await rename(await v.path(),path.join(here,'demo.webm'));report.video='demo.webm';}
}catch(e){report.errors.push(e.stack||String(e));}
finally{
 await browser.close();await vite.close();server.close();await app.close?.().catch(()=>{});
 await writeFile(path.join(here,'render-report.json'),JSON.stringify(report,null,1));
 await rm(temp,{recursive:true,force:true}).catch(()=>{});
 console.log(report.shots.map(s=>s.file).join('\n'));if(report.errors.length)console.log('ERRORS\n'+report.errors.join('\n'));
 process.exit(report.errors.length?1:0);
}
